Method.Implementation:

	 try{
		 do ##super()
		$$$TRACE("Connect to " _ ..ApplicationAddress)		
		set ..objCdrTuxService = ##class(org.ihc.itf.cdr.voser.HasAdmitPrivilegeFromCode).%New(..JavaGateway,..ApplicationAddress, ..TuxedoService, ..LogDirectory _"/" _$$$JobConfigName _".log", $$$ConfigTrace($$$JobConfigName))		
     	set status = ..CheckObject()
	}catch err{
		$$$LOGERROR("Exception while Creating Tuxedo Service: " _err.AsSystemError() _ " _ data: " _ err.Data _ "; code:" _ err.Code)	    
	    Set status = ##class(IHC.ITF.ITFCOMMON.Utility).RetryMsgError(..%ConfigName," Exception while Creating Tuxedo Service: "_err.AsSystemError()_"::"_err.Data_"::"_err.Code)
	}

	quit status

	 set status = $$$OK
	 $$$TRACE("Inside OnMessage method......")

	 $$$TRACE("objCdrTuxService Object valid: "_$IsObject(..objCdrTuxService))
	 try{ 		 
		 if (..CheckObject() '= $$$OK) {
		 	$$$TRACE("**** Object does not exists ****")
		 	// Try to re intialize
		 	set result = ..OnInit()
			if (result '= $$$OK)
			{
				set status = ##class(IHC.ITF.ITFCOMMON.Utility).DisableMsgError("Op-AdmitPrivilege", "Get admit privilege failed. For : " _pRequest.StringValue_ " ; Reason: " _ result)						
				return status
			}
	 	}

	 	set pResponse = ##class(Ens.StringResponse).%New()
	 	set pResponse.StringValue=""
	 	set args = pRequest.StringValue
	 	$$$TRACE("Call method getAdmitPrivilege("_$P(args,";",1)_","_$P(args,";",3)_","_$P(args,";",2)_","_$P(args,";",4)_")")
 		set output = ..objCdrTuxService.getAdmitPrivilege($P(args,";",1),$P(args,";",3),$P(args,";",2),$P(args,";",4))
		$$$TRACE("Output after invocation of getAdmitPrivilege Java Method:"_output)

		if (output'=""){
			set pResponse.StringValue = output
		}

	 }catch err{
		 $$$TRACE("Exception while getting admit privilege: " _err.AsSystemError() _ " _ data: " _ err.Data _ "; code:" _ err.Code)
	     Set status = ..ExceptionHandler(err, "OnMessage")
	 }


	 return status
